example.code:
slsaProvenance {
    signer = kmsDefaultChain {
        region = "us-east-1"
        keyId = "arn:aws:kms:us-east-1:123456789012:key/abcd-1234"
        signingAlgorithm = "ECDSA_SHA_256"
    }
}

slsaProvenance {
    signer = kmsAssumeRole {
        region = "us-east-1"
        keyId = "alias/slsa-signer"
        signingAlgorithm = "ECDSA_SHA_256"
        roleArn = "arn:aws:iam::123456789012:role/tc-slsa-signer"
    }
    failBuildOnError = true
}
